def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    if not text:
        return []

    rows = []
    n = len(text)
    i = 0

    while i < n:
        row = []
        # Bir satırın başlangıcı

        while True:
            # 1. Alan (Field) ayrıştırma
            if i < n and text[i] == '"':
                # Tırnaklı alan
                i += 1
                field_chars = []
                closed = False
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i+1] == '"':
                            field_chars.append('"')
                            i += 2
                        else:
                            closed = True
                            i += 1
                            break
                    else:
                        field_chars.append(text[i])
                        i += 1

                if not closed:
                    raise ValueError("Unclosed quote")
                if i < n and text[i] not in (delimiter, '\r', '\n'):
                    raise ValueError("Invalid character after closing quote")

                row.append("".join(field_chars))
            else:
                # Tırnaksız alan
                start = i
                while i < n and text[i] not in (delimiter, '\r', '\n'):
                    i += 1
                row.append(text[start:i])

            # 2. Alan sonu kontrolü (Delimiter, Newline veya EOF)
            if i < n and text[i] == delimiter:
                i += 1
                # Delimiter sonrası newline gelirse boş alan ekle
                if i < n and text[i] in ('\r', '\n'):
                    row.append("")
                    # Newline'ı tüketmek üzere döngüden çık
                    break
                # Delimiter metnin sonundaysa
                elif i == n:
                    row.append("")
                    break
                # Sadece delimiter, bir sonraki alana devam et
                else:
                    continue
            elif i < n and text[i] in ('\r', '\n'):
                # Satır sonu geldi
                break
            else:
                # EOF veya beklenmedik durum
                break

        rows.append(row)

        # 3. Satır sonu karakterlerini tüket (CR, LF veya CRLF)
        if i < n and text[i] in ('\r', '\n'):
            if text[i] == '\r' and i + 1 < n and text[i+1] == '\n':
                i += 2
            else:
                i += 1

            # Eğer metin bir newline ile bittiyse, yeni bir satır oluşturmaması için
            # döngüden önce i'yi kontrol etmeliyiz.
            if i == n:
                break
        elif i >= n:
            break
        else:
            # Eğer bir field bitişi nedeniyle break yapıldıysa (örn. delimiter sonrası newline)
            # i zaten newline üzerinde veya sonrasında olabilir, ama döngü yapısı i'yi ilerletmeli.
            pass

        # Eğer i metin sonuna ulaştıysa ama döngü içindeki break'lerden dolayı i hala bir newline üzerinde değilse,
        # bu durum metnin sonundaki newline durumunu kontrol etmek içindir.
        if i >= n:
            break

    return rows

